#include <stdio.h>
#define PI 3
int main(void) {
    int r = 2;
    printf("%d\n", PI * r * r);
    return 0;
}

#include <stdio.h>
#define MODE 1
#if MODE == 1
#define MSG "Hello"
#else
#define MSG "World"
#endif
int main(void) {
    printf("%s\n", MSG);
    return 0;
}

#include <stdio.h>
#define SQ(x) ((x) * (x))
int main(void) {
    printf("%d\n", SQ(3 + 1));
    return 0;
}

#include <stdio.h>
#define MAX(a, b) ((a) > (b) ? (a) : (b))
int main(void) {
    printf("%d\n", MAX(5, 9));
    return 0;
}

#include <stdio.h>
#define VAL 10
#ifdef VAL
int x = VAL;
#else
int x = 0;
#endif
int main(void) {
    printf("%d\n", x);
    return 0;
}

#include <stdio.h>
#define DOUBLE(x) ((x) + (x))
int main(void) {
    int a = 5;
    printf("%d\n", DOUBLE(a) * DOUBLE(a));
    return 0;
}

#include <stdio.h>
#define VERSION 2
#if VERSION >= 3
#define OUT "v3+"
#elif VERSION == 2
#define OUT "v2"
#else
#define OUT "v1"
#endif
int main(void) {
    printf("%s\n", OUT);
    return 0;
}

#include <stdio.h>
#define DEBUG 1
int main(void) {
    int n = 7;
#ifdef DEBUG
    n = n * 2;
#endif
    printf("%d\n", n);
    return 0;
}

#include <stdio.h>
#define ABS(x) ((x) < 0 ? -(x) : (x))
int main(void) {
    int a = ABS(-5);
    int b = ABS(3);
    printf("%d %d\n", a, b);
    return 0;
}
